    10→use super::errors::VerifierError;
    11→use crate::{
    12→    fk20::cosets::{coset_gens, reverse_bit_order},
    13→    verification_key::VerificationKey,
    14→};
    15→
    16→/// CosetIndex is a reference to a coset.
    17→///
    18→/// Note: We are able to use CosetIndex instead of the coset because
    19→/// the prover and verifier both know what the cosets are that
    20→/// we will be making and verifying opening proofs for.
    21→pub type CosetIndex = u64;
    22→
    23→/// CommitmentIndex is a reference to a commitment.
    24→///
    25→/// In order to make verification cheaper, the verifier will
    26→/// deduplicate the list of commitments that are needed in order to verify opening proofs.
    27→/// They will then refer to a commitment via its position in an array of deduplicated commitments
    28→/// with the CommitmentIndex.
    29→pub type CommitmentIndex = u64;
    30→
    31→/// FK20Verifier initializes all of the components needed to verify KZG multi point
    32→/// proofs that were created using the FK20Prover.
    33→///
    34→/// Note: The proofs can be created naively not using the FK20 strategy (see naive.rs)
    35→/// however, we put FK20 in the name since:
    36→///  - From the callers perspective, this distinction is not important
    37→///  - We only use FK20 to create proofs
    38→#[derive(Debug)]
    39→pub struct FK20Verifier {
    40→    pub verification_key: VerificationKey,
    41→    pub coset_gens_bit_reversed: Vec<Scalar>,
    42→    coset_domain: Domain,
    43→    // Pre-computations for the verification algorithm
    44→    //
    45→    // [tau^n]_2
    46→    tau_pow_n: G2Prepared,
    47→    // [-1]_2
    48→    neg_g2_gen: G2Prepared,
    49→    // Bit reversed vector of the coset generators raised
    50→    // to the power of `n`, needed to verify a multi opening proof.
    51→    pub bit_reversed_coset_gens_pow_n: Vec<Scalar>,
    52→    // Bit reversed vector of the coset generators that
    53→    // we will use to compute an inverse coset IFFT.
    54→    bit_reversed_coset_fft_gens: Vec<CosetFFT>,
    55→}
    56→
    57→impl FK20Verifier {
    58→    pub fn new(
    59→        verification_key: VerificationKey,
    60→        num_points_to_open: usize,
    61→        num_cosets: usize,
    62→    ) -> Self {
    63→        const BIT_REVERSED: bool = true;
    64→
    65→        assert!(
    66→            verification_key.coset_size.is_power_of_two(),
    67→            "coset size must be a power of two"
    68→        );
    69→        assert!(
    70→            num_cosets * verification_key.coset_size == num_points_to_open,
    71→            "Expected {} * {} == {}",
    72→            num_cosets,
    73→            verification_key.coset_size,
    74→            num_points_to_open
    75→        );
    76→
    77→        let coset_gens = coset_gens(num_points_to_open, num_cosets, BIT_REVERSED);
    78→
    79→        let coset_size = num_points_to_open / num_cosets;
    80→        assert!(
    81→            verification_key.g2s.len() >= coset_size,
    82→            "need as many g2 points as coset size"
    83→        );
    84→        let coset_domain = Domain::new(verification_key.coset_size);
    85→
    86→        let n = verification_key.coset_size;
    87→        // [tau^n]_2
    88→        let tau_pow_n = G2Prepared::from(verification_key.g2s[n]);
    89→        // [-1]_2
    90→        let neg_g2_gen = G2Prepared::from(-verification_key.g2_gen);
    91→
    92→        let coset_gens_pow_n = coset_gens
    93→            .iter()
    94→            .map(|&coset_gen| coset_gen.pow_vartime([n as u64]))
    95→            .collect();
    96→
    97→        let coset_fft_gens = coset_gens.iter().map(|gen| CosetFFT::new(*gen)).collect();
    98→
    99→        Self {
   100→            verification_key,
   101→            coset_gens_bit_reversed: coset_gens,
   102→            coset_domain,
   103→            tau_pow_n,
   104→            neg_g2_gen,
   105→            bit_reversed_coset_gens_pow_n: coset_gens_pow_n,
   106→            bit_reversed_coset_fft_gens: coset_fft_gens,
   107→        }
   108→    }
   109→
   110→    /// Verify multiple multi-opening proofs.
   111→    ///
   112→    /// Panics if the following slices do not have the same length:
   113→    ///
   114→    /// - commitment_indices
   115→    /// - bit_reversed_coset_indices
   116→    /// - bit_reversed_coset_evals
   117→    /// - bit_reversed_proofs
   118→    ///
   119→    /// This corresponds to the guarantee that every opening should have an `input_point` and an `output_point`
   120→    /// with a corresponding proof attesting to `f(input_point) = output_point` and a commitment to the polynomial `f`.
   121→    ///
   122→    /// Note: Although this method is on the `FK20Verifier` structure, it is possible to verify methods that are not
   123→    /// created by the `FK20Prover`. FK20Prover generates multi-proofs efficiently using the FK20 strategy, but we
   124→    /// could just as well generate those proofs using the naive strategy that we test FK20 against. We leave this
   125→    /// naming as is since it conveys a meaningful difference between the other internal provers which do not use FK20.
   126→    /// On the API level, we however export this as Verifier.
   127→    ///
   128→    /// The matching function in the spec is: https://github.com/ethereum/consensus-specs/blob/13ac373a2c284dc66b48ddd2ef0a10537e4e0de6/specs/_features/eip7594/polynomial-commitments-sampling.md#verify_cell_kzg_proof_batch_impl
   129→    pub fn verify_multi_opening(
   130→        &self,
   131→
   132→        deduplicated_commitments: &[G1Point],
   133→        commitment_indices: &[CommitmentIndex],
   134→
   135→        bit_reversed_coset_indices: &[CosetIndex],
   136→        bit_reversed_coset_evals: &[Vec<Scalar>],
   137→        bit_reversed_proofs: &[G1Point],
   138→    ) -> Result<(), VerifierError> {
   139→        assert_eq!(
   140→            commitment_indices.len(),
   141→            bit_reversed_proofs.len(),
   142→            "Expected to have a proof for each commitment opening"
   143→        );
   144→        assert_eq!(
   145→            bit_reversed_coset_indices.len(),
   146→            bit_reversed_proofs.len(),
   147→            "Expected to have a proof for each index we want to open at"
   148→        );
   149→        assert_eq!(
   150→            bit_reversed_coset_evals.len(),
   151→            bit_reversed_proofs.len(),
   152→            "Expected to have a proof for each evaluation we want to prove an opening for"
   153→        );
   154→        let all_same_size = bit_reversed_coset_evals
   155→            .windows(2)
   156→            .all(|w| w[0].len() == w[1].len());
   157→        assert!(
   158→            all_same_size,
   159→            "Expected all cosets to have the same number of elements"
   160→        );
   161→
   162→        // The batch size corresponds to how many openings, we ultimately want to be verifying.
   163→        let batch_size = bit_reversed_coset_indices.len();
   164→
   165→        // 1. Compute random challenges for batching the opening together.
   166→        //
   167→        // From hereon out, `random` will refer to using these random challenges.
   168→        //
   169→        // We compute one challenge `r` using fiat-shamir and the rest are powers of `r`
   170→        // This is safe because of the Schwartz-Zippel Lemma.
   171→        let r = compute_fiat_shamir_challenge(
   172→            &self.verification_key,
   173→            deduplicated_commitments,
   174→            commitment_indices,
   175→            bit_reversed_coset_indices,
   176→            bit_reversed_coset_evals,
   177→            bit_reversed_proofs,
   178→        );
   179→        let r_powers = compute_powers(r, batch_size);
   180→        let num_unique_commitments = deduplicated_commitments.len();
   181→
   182→        // 2. Compute a random linear combination of the proofs
   183→        //
   184→        // Safety: This unwrap can never trigger because `r_powers.len()` is `batch_size`
   185→        // and `bit_reversed_proofs.len()` will equal `batch_size` since we must have a proof for each item in the batch.
   186→        let comm_random_sum_proofs = g1_lincomb(bit_reversed_proofs, &r_powers)
   187→            .expect("number of proofs and number of r_powers should be the same");
   188→
   189→        // 3. Compute a weighted random linear combination of the proofs
   190→        //
   191→        // Where the `weight` refers to the coset_generators to the power of `n`
   192→        let mut weighted_r_powers = Vec::with_capacity(batch_size);
   193→        for (bit_reversed_coset_index, r_power) in bit_reversed_coset_indices.iter().zip(&r_powers)
   194→        {
   195→            let coset_gen_pow_n =
   196→                self.bit_reversed_coset_gens_pow_n[*bit_reversed_coset_index as usize];
   197→            weighted_r_powers.push(r_power * coset_gen_pow_n);
   198→        }
   199→        // Safety: This should never panic since `bit_reversed_proofs.len()` is equal to the batch_size.
   200→        let random_weighted_sum_proofs = g1_lincomb(bit_reversed_proofs, &weighted_r_powers)
   201→            .expect("number of proofs and number of weighted_r_powers should be the same");
   202→
   203→        // 4. Compute a random linear combination of the commitments
   204→        //
   205→        // For each commitment_index/commitment, we add its contribution of `r` to
   206→        // the associated weight for that commitment.
   207→        //
   208→        // This is essentially taking advantage of the fact that commitments may be
   209→        // duplicated., so instead of calculating C = r_0 * C_0 + r_1 * C_0 naively
   210→        // which would require a size 2 MSM, we compute C = (r_0 + r_1) * C_0
   211→        // which would require a size 1 MSM and some extra field additions.
   212→        //
   213→        // One can view this as trading a scalar multiplication for a field addition.
   214→        //
   215→        // The extra field additions are being calculated in the for loop below.
   216→        let mut weights = vec![Scalar::ZERO; num_unique_commitments];
   217→        for (commitment_index, r_power) in commitment_indices.iter().zip(&r_powers) {
   218→            weights[*commitment_index as usize] += r_power;
   219→        }
   220→        // Safety: This unwrap will never trigger because the length of `weights` has been initialized
   221→        // to be `deduplicated_commitments.len()`.
   222→        //
   223→        // This only panics, if `deduplicated_commitments.len()` != `weights.len()`
   224→        let random_sum_commitments = g1_lincomb(deduplicated_commitments, &weights)
   225→            .expect("number of row_commitments and number of weights should be the same");
   226→
   227→        // 5. Compute random linear combination of the interpolation polynomials
   228→        let random_sum_interpolation_poly = compute_sum_interpolation_poly(
   229→            &self.coset_domain,
   230→            &self.bit_reversed_coset_fft_gens,
   231→            bit_reversed_coset_evals,
   232→            bit_reversed_coset_indices,
   233→            &r_powers,
   234→        );
   235→        let comm_random_sum_interpolation_poly = self
   236→            .verification_key
   237→            .commit_g1(&random_sum_interpolation_poly);
   238→
   239→        // 6. Compute pairing check
   240→        //
   241→        // Note: This variable is `rl` in the specs.
   242→        let pairing_input_g1 = (random_sum_commitments - comm_random_sum_interpolation_poly)
   243→            + random_weighted_sum_proofs;
   244→
   245→        // The pairings function requires elements in affine representation, so we must batch normalize the
   246→        // pairing inputs.
   247→        let normalized_vectors = g1_batch_normalize(&[comm_random_sum_proofs, pairing_input_g1]);
   248→        let random_sum_proofs = normalized_vectors[0];
   249→        let pairing_input_g1 = normalized_vectors[1];
   250→
   251→        let proof_valid = multi_pairings(&[
   252→            (&random_sum_proofs, &self.tau_pow_n),
   253→            (&pairing_input_g1, &self.neg_g2_gen),
   254→        ]);
   255→        if proof_valid {
   256→            Ok(())
   257→        } else {
   258→            Err(VerifierError::InvalidProof)
   259→        }
   260→    }
   261→}
   262→
   263→/// Computes a random challenge which will allow us to efficiently verify multiple opening proofs.
   264→///
   265→/// Efficiently refers to being able to verify these proofs faster than verifying each proof individually.
   266→///
   267→/// The matching function in the spec is: https://github.com/ethereum/consensus-specs/blob/13ac373a2c284dc66b48ddd2ef0a10537e4e0de6/specs/_features/eip7594/polynomial-commitments-sampling.md#compute_verify_cell_kzg_proof_batch_challenge
   268→#[allow(clippy::manual_slice_size_calculation)]
   269→fn compute_fiat_shamir_challenge(
   270→    verification_key: &VerificationKey,
   271→    row_commitments: &[G1Point],
   272→    row_indices: &[u64],
   273→    coset_indices: &[u64],
   274→    coset_evals: &[Vec<Scalar>],
   275→    proofs: &[G1Point],
   276→) -> Scalar {
   277→    const DOMAIN_SEP: &str = "RCKZGCBATCH__V1_";
   278→    let hash_input_size = DOMAIN_SEP.len()
   279→            + size_of::<u64>() // polynomial bound
   280→            + size_of::<u64>() // field elements per coset
   281→            + size_of::<u64>() // num commitments
   282→            + size_of::<u64>() // num cosets
   283→            + row_commitments.len() * G1Point::compressed_size()
   284→            + row_indices.len() * size_of::<u64>()
   285→            + coset_indices.len() * size_of::<u64>()
   286→            + coset_evals.len() * verification_key.coset_size * size_of::<Scalar>()
   287→            + proofs.len() * G1Point::compressed_size();
   288→
   289→    let mut hash_input: Vec<u8> = Vec::with_capacity(hash_input_size);
   290→
   291→    hash_input.extend(DOMAIN_SEP.as_bytes());
   292→    hash_input.extend((verification_key.num_coefficients_in_polynomial as u64).to_be_bytes());
   293→    hash_input.extend((verification_key.coset_size as u64).to_be_bytes());
   294→
   295→    let num_commitments = row_commitments.len() as u64;
   296→    hash_input.extend(num_commitments.to_be_bytes());
   297→
   298→    let num_cosets = coset_indices.len() as u64;
   299→    hash_input.extend(num_cosets.to_be_bytes());
   300→
   301→    for commitment in row_commitments {
   302→        hash_input.extend(commitment.to_compressed());
   303→    }
   304→
   305→    for k in 0..num_cosets {
   306→        hash_input.extend(row_indices[k as usize].to_be_bytes());
   307→        hash_input.extend(coset_indices[k as usize].to_be_bytes());
   308→        for eval in &coset_evals[k as usize] {
   309→            hash_input.extend(eval.to_bytes_be());
   310→        }
   311→        hash_input.extend(proofs[k as usize].to_compressed());
   312→    }
   313→
   314→    assert_eq!(hash_input.len(), hash_input_size);
   315→    let mut hasher = Sha256::new();
   316→    hasher.update(hash_input);
   317→    let result: [u8; 32] = hasher.finalize().into();
   318→
   319→    // For randomization, we only need a 128 bit scalar, since this is used for batch verification.
   320→    // See for example, the randomizers section in : https://cr.yp.to/badbatch/badbatch-20120919.pdf
   321→    //
   322→    // This is noted because when we convert a 256 bit hash to a scalar, a bias will be introduced.
   323→    // This however does not affect our security guarantees because the bias is negligible given we
   324→    // want a uniformly random 128 bit integer.
   325→    //
   326→    // Also there is a negligible probably that the scalar is zero, so we do not handle this case here.
   327→    reduce_bytes_to_scalar_bias(result)
   328→}
   329→
   330→/// Computes a vector of powers of a given scalar value.
   331→///
   332→/// Example: compute_powers(x, 5) = [1, x, x^2, x^3, x^4]
   333→fn compute_powers(value: Scalar, num_elements: usize) -> Vec<Scalar> {
   334→    let mut powers = Vec::with_capacity(num_elements);
   335→    let mut current_power = Scalar::ONE;
   336→
   337→    for _ in 0..num_elements {
   338→        powers.push(current_power);
   339→        current_power *= value;
   340→    }
   341→
   342→    powers
   343→}
   344→
   345→/// Computes `k` Interpolation polynomials and then combines
   346→/// them linearly using `k` values from `r_powers`.
   347→/// The computed value is I(X) = I_0(x) + r * I_1(x) + ... + r^{n-1} * I_{n-1}(x)
   348→fn compute_sum_interpolation_poly(
   349→    coset_domain: &Domain,
   350→    bit_reversed_coset_fft_gens: &[CosetFFT],
   351→    bit_reversed_coset_evals: &[Vec<Scalar>],
   352→    bit_reversed_coset_indices: &[CosetIndex],
   353→    r_powers: &[Scalar],
   354→) -> PolyCoeff {
   355→    let mut random_sum_interpolation_poly = PolyCoeff::default();
   356→
   357→    for ((mut bit_reversed_coset_eval, bit_reversed_coset_index), scale_factor) in
   358→        bit_reversed_coset_evals
   359→            .iter()
   360→            .cloned()
   361→            .zip(bit_reversed_coset_indices)
   362→            .zip(r_powers)
   363→    {
   364→        // Reverse the order, so it matches the fft domain
   365→        reverse_bit_order(&mut bit_reversed_coset_eval);
   366→        let coset_eval = bit_reversed_coset_eval; // variable rename since we un-bit reversed the vector
   367→
   368→        // Compute the interpolation polynomial using a coset fft
   369→        let coset_gen = &bit_reversed_coset_fft_gens[*bit_reversed_coset_index as usize];
   370→        let ifft_scalars = coset_domain.coset_ifft_scalars(coset_eval, coset_gen);
   371→
   372→        // Scale the interpolation polynomial by the challenge
   373→        let scaled_interpolation_poly = ifft_scalars
   374→            .0
   375→            .into_iter()
   376→            .map(|coeff| coeff * scale_factor)
   377→            .collect::<Vec<_>>();
   378→
   379→        random_sum_interpolation_poly =
   380→            random_sum_interpolation_poly.add(&scaled_interpolation_poly.into());
   381→    }
   382→
   383→    random_sum_interpolation_poly
   384→}
   385→
   386→#[cfg(test)]
   387→mod tests {
   388→    use bls12_381::Scalar;
   389→
   390→    use super::*;
   391→
   392→    #[test]
   393→    fn test_compute_powers() {
   394→        let base = Scalar::from(2u64);
   395→        let num_elements = 5;
   396→
   397→        let powers = compute_powers(base, num_elements);
   398→
   399→        assert_eq!(powers.len(), num_elements);
   400→        assert_eq!(powers[0], Scalar::ONE);
   401→        assert_eq!(powers[1], base);
   402→        assert_eq!(powers[2], base.pow_vartime([2]));
   403→        assert_eq!(powers[3], base.pow_vartime([3]));
   404→        assert_eq!(powers[4], base.pow_vartime([4]));
   405→
   406→        let powers = compute_powers(base, 0);
   407→        assert!(powers.is_empty());
   408→    }
   409→}
   410→

