    22→
    23→/// FK20Prover initializes all of the components needed to compute a KZG multi point
    24→/// proof using the FK20 method.
    25→///
    26→/// The FK20 method gives an efficient algorithm for opening points, where
    27→/// the points are roots of unity. (It cannot be used to open arbitrary points)
    28→///
    29→/// See [Fk21](https://github.com/khovratovich/Kate/blob/master/Kate_amortized.pdf) for details
    30→/// on the scheme.
    31→#[derive(Debug)]
    32→pub struct FK20Prover {
    33→    batch_toeplitz: BatchToeplitzMatrixVecMul,
    34→    /// The amount of points that a single proof will attest to the opening of.
    35→    ///
    36→    /// Note: FK20 allows you to create a proof of an opening for multiple points.
    37→    /// Each proof will attest to the opening of `l` points.
    38→    /// In the FK20 paper, this is also referred to as `l` (ELL).
    39→    coset_size: usize,
    40→    /// The total number of points that we want to open a polynomial at.
    41→    ///
    42→    /// Note: A proof will attest to `point_set_size` of these points at a
    43→    /// time.
    44→    number_of_points_to_open: usize,
    45→
    46→    /// Domain used in FK20 to create the opening proofs
    47→    proof_domain: Domain,
    48→    /// Domain used to evaluate the polynomial at the points we want to open at.
    49→    evaluation_domain: Domain,
    50→    /// Domain used for converting polynomial to monomial form.
    51→    poly_domain: Domain,
    52→    /// Commitment key used for committing to the polynomial
    53→    /// in monomial form.
    54→    commit_key: CommitKey,
    55→}
    56→
    57→impl FK20Prover {
    58→    /// Initialize a FK20 struct with the given parameters.
    59→    ///
    60→    /// commit_key: The commitment key used to commit to polynomials.
    61→    /// polynomial_bound: The number of coefficients in the polynomial.
    62→    /// points_per_proof: The number of points that a single proof will attest to.
    63→    /// number_of_points_to_open: The total number of points that we want to open a polynomial at.
    64→    pub fn new(
    65→        commit_key: CommitKey,
    66→        polynomial_bound: usize,
    67→        points_per_proof: usize,
    68→        number_of_points_to_open: usize,
    69→        use_precomp: UsePrecomp,
    70→    ) -> Self {
    71→        assert!(
    72→            points_per_proof.is_power_of_two()
    73→                && number_of_points_to_open.is_power_of_two()
    74→                && number_of_points_to_open > points_per_proof
    75→                && polynomial_bound.is_power_of_two()
    76→                && commit_key.g1s.len() >= polynomial_bound
    77→                && commit_key.g1s.len() > points_per_proof
    78→        );
