    85→        // KZG polynomial commitment scheme for opening a polynomial at a single point
    86→        // does not require all of the coefficients of the polynomial to compute
    87→        // the quotient polynomial.
    88→        let srs_truncated: Vec<_> = commit_key
    89→            .g1s
    90→            .iter()
    91→            .rev()
    92→            .skip(points_per_proof)
    93→            .copied()
