   118→            coset_size: points_per_proof,
   119→            number_of_points_to_open,
   120→            proof_domain,
   121→            evaluation_domain,
   122→            poly_domain,
   123→            commit_key,
   124→        }
   125→    }
   126→
   127→    /// Commit to the `Input` that we will be creating FK20 proofs over.
   128→    pub fn commit(&self, input: Input) -> G1Point {
   129→        let poly_coeff = match input {
   130→            Input::PolyCoeff(poly_coeff) => poly_coeff,
